INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/09/15 15:00:00", 2, 6.5, -470.0, 10008, 0.0, "ヴルム", "2023/12/22 14:59:59", 2002, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, 2, 127802, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/15 15:00:00", 2, 0.0, -470.0, 10009, 0.0, "アネモネ", "2024/03/22 14:59:59", 2002, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 3, 1, 129602, 1);
