INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/15 15:00:00", 1, 0.0, -470.0, 10011, 0.0, "ネフィ=ネラ", "2024/03/22 14:59:59", 2002, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 3, 1, 129701, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/15 15:00:00", 2, 6.2, -470.0, 10012, 0.0, "ネフィ=ネラ", "2024/03/22 14:59:59", 2002, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 3, 2, 129701, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/15 15:00:00", 3, 3.1, -470.0, 10013, 0.0, "カノン", "2024/06/22 14:59:59", 2002, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 4, 1, 130301, 5);
