INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/15 15:00:00", 2, 0.0, -470.0, 10015, 0.0, "ナーナ", "2024/06/22 14:59:59", 2002, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 4, 1, 130401, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/15 15:00:00", 2, 3.35, -470.0, 10016, 0.0, "ナーナ", "2024/06/22 14:59:59", 2002, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 4, 2, 130401, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/15 15:00:00", 1, 0.0, -470.0, 10017, 0.0, "ホウオウ", "2024/09/22 14:59:59", 2002, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 5, 1, 130502, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/15 15:00:00", 2, 3.18, -470.0, 10018, 0.0, "ホウオウ", "2024/09/22 14:59:59", 2002, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 5, 2, 130502, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/15 15:00:00", 4, 0.0, -470.0, 10019, 0.0, "ホウオウ", "2024/09/22 14:59:59", 2002, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 5, 3, 130503, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/15 15:00:00", 1, 4.9, -470.0, 10020, 0.0, "ネア", "2024/09/22 14:59:59", 2002, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 5, 1, 123301, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/15 15:00:00", 1, 4.8, -470.0, 10021, 0.0, "ネア", "2024/09/22 14:59:59", 2002, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 5, 2, 123301, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/15 15:00:00", 3, 4.922, -470.0, 10022, 0.0, "カリザ", "2024/12/22 14:59:59", 2002, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 6, 1, 133301, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/15 15:00:00", 3, 9.638, -470.0, 10023, 0.0, "カリザ", "2024/12/22 14:59:59", 2002, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 6, 2, 133301, 5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/15 15:00:00", 1, 2.88, -470.0, 10024, 0.0, "ミーア", "2024/12/22 14:59:59", 2002, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 6, 1, 133401, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/15 15:00:00", 5, 4.818, -470.0, 10025, 0.0, "ミーア", "2024/12/22 14:59:59", 2002, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 6, 2, 133401, 1);
