INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/15 15:00:00", 2, 5.53, -470.0, 10030, 0.0, "ルルィ", "2025/06/23 14:59:59", 2002, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 8, 1, 136902, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/15 15:00:00", 9, 6.05, -470.0, 10031, 0.0, "ルルィ", "2025/06/23 14:59:59", 2002, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 8, 2, 136902, 7);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/15 15:00:00", 2, 0.0, -470.0, 10032, 0.0, "デュラン", "2025/06/23 14:59:59", 2002, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 8, 1, 137001, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/15 15:00:00", 2, 0.0, -470.0, 10033, 0.0, "デュラン", "2025/06/23 14:59:59", 2002, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 8, 2, 137001, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/16 15:00:00", 2, 0.0, -470.0, 10034, 0.0, "サツキ", "2025/09/23 14:59:59", 2002, "おう\n好きなもん持ってきな", 9, 1, 135902, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/16 15:00:00", 1, 4.935, -470.0, 10035, 0.0, "サツキ", "2025/09/23 14:59:59", 2002, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 9, 2, 135902, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/16 15:00:00", 2, 7.441, -470.0, 10036, 0.0, "ユキノ", "2025/09/23 14:59:59", 2002, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 9, 1, 135802, 5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/16 15:00:00", 7, 0.0, -470.0, 10037, 0.0, "ユキノ", "2025/09/23 14:59:59", 2002, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 9, 2, 135802, 7);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/16 15:00:00", 2, 2.295, -470.0, 10038, 0.0, "クルル", "2025/12/22 14:59:59", 2002, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 10, 1, 130901, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/16 15:00:00", 1, 6.281, -470.0, 10039, 0.0, "クルル", "2025/12/22 14:59:59", 2002, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 10, 2, 130901, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/16 15:00:00", 2, 5.549, -470.0, 10040, 0.0, "ヴォルガーノ", "2025/12/22 14:59:59", 2002, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 10, 1, 137701, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/16 15:00:00", 3, 2.64, -470.0, 10041, 0.0, "ヴォルガーノ", "2025/12/22 14:59:59", 2002, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 10, 2, 137701, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/15 15:00:00", 7, 7.642, -470.0, 10042, 0.0, "ライラエル", "2026/03/23 11:59:59", 2002, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 11, 1, 132801, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/15 15:00:00", 1, 0.0, -470.0, 10043, 0.0, "ライラエル", "2026/03/23 11:59:59", 2002, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 11, 2, 132802, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/15 15:00:00", 1, 0.0, -470.0, 10044, 0.0, "クローチェ", "2026/03/23 11:59:59", 2002, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 11, 1, 134502, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/15 15:00:00", 2, 3.72, -470.0, 10045, 0.0, "クローチェ", "2026/03/23 11:59:59", 2002, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 11, 2, 134501, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/16 12:00:00", 2, 4.991, -470.0, 10046, 0.0, "ネフィ＝ネラ", "2026/06/22 11:59:59", 2002, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 12, 1, 138201, 1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/16 12:00:00", 1, 3.877, -470.0, 10047, 0.0, "ネフィ＝ネラ", "2026/06/22 11:59:59", 2002, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 12, 2, 138201, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/16 12:00:00", 4, 1.71, -470.0, 10048, 0.0, "アラクネ", "2026/06/22 11:59:59", 2002, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 12, 1, 136001, 6);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/16 12:00:00", 5, 5.32, -470.0, 10049, 0.0, "アラクネ", "2026/06/22 11:59:59", 2002, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 12, 2, 136001, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/15 12:00:00", 9, 3.727, -470.0, 10050, 0.0, "アネモネ", "2026/09/22 11:59:59", 2002, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 13, 1, 135401, 4);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/15 12:00:00", 7, 7.213, -470.0, 10051, 0.0, "アネモネ", "2026/09/22 11:59:59", 2002, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 13, 2, 135401, 9);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/15 12:00:00", 1, 1.874, -470.0, 10052, 0.0, "クリア", "2026/09/22 11:59:59", 2002, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 13, 1, 135301, 2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/15 12:00:00", 2, 0.0, -470.0, 10053, 0.0, "クリア", "2026/09/22 11:59:59", 2002, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 13, 2, 135301, 2);
